/* rev-on-scroll */
const obs = new IntersectionObserver((es) => {
  const visible = es.filter(e => e.isIntersecting && !e.target.classList.contains('active'));
  visible.forEach((e, i) => {
    setTimeout(() => {
      e.target.classList.add('active');
    }, i * 150);
  });
}, { threshold: 0.1, rootMargin: '0px 0px -100px 0px' });
const scan = () => document.querySelectorAll('.rev-on-scroll:not(.active)').forEach(el => obs.observe(el));
const mo = new MutationObserver(scan);
mo.observe(document.body, { childList: true, subtree: true });
scan();
/* /rev-on-scroll */
